"""Dates, members, fees and permits for the hiking club: members."""


def age_on(birth, today):
    years = today[0] - birth[0]
    if (today[1], today[2]) < (birth[1], birth[2]):
        years -= 1
    return years


def member_class(birth, today):
    age = age_on(birth, today)
    if age < 14:
        return "junior"
    if age >= 65:
        return "senior"
    return "adult"

