import json
import unittest

import importlib

def run_case(case):
    if case[0] == 'app':
        app = importlib.import_module('trailclub.app')
        return app.month_end(*case[1])
    util = importlib.import_module('trailclub.util')
    return getattr(util, case[0])(*case[1])

def norm(x):
    return json.loads(json.dumps(x))


class UtilTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("[\"is_leap\", [2000]]")
        self.assertEqual(norm(run_case(case)), json.loads("true"))

    def test_example_2(self):
        case = json.loads("[\"is_leap\", [2023]]")
        self.assertEqual(norm(run_case(case)), json.loads("false"))

    def test_example_3(self):
        case = json.loads("[\"app\", [[[\"m0\", [1990, 8, 5], [2025, 4, 6]], [\"m1\", [2010, 2, 1], [2025, 4, 5]]], [2025, 6, 15]]]")
        self.assertEqual(norm(run_case(case)), json.loads("[{\"name\": \"m0\", \"class\": \"adult\", \"fee\": 45, \"late_days\": 70}, {\"name\": \"m1\", \"class\": \"adult\", \"fee\": 45, \"late_days\": 71}]"))


if __name__ == '__main__':
    unittest.main()

