"""Dates, members, fees and permits for the hiking club: fees."""

from .dates import days_between
from .members import member_class


CLASS_PERCENT = {"junior": 50, "adult": 100, "senior": 70}


def annual_fee(birth, today):
    return 75 * CLASS_PERCENT[member_class(birth, today)] // 100


def fee_with_late(birth, today, due):
    """The annual fee, with a surcharge once the due date is more than 30 days past."""
    fee = annual_fee(birth, today)
    late = days_between(due, today) if due <= today else 0
    if late > 30:
        fee += fee * 10 // 100
    return fee

